import {Battle,LEADERS,CARDS} from './sim.js';
import {BattlefieldRenderer} from './renderer.js';
const $=id=>document.getElementById(id),time=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;
let chosen='indigo';try{const saved=localStorage.getItem('oath-live-leader');if(LEADERS[saved])chosen=saved;}catch{}
let battle=new Battle(chosen),lane=1,running=false,paused=false,speed=1,uiTimer=0,handStamp='',noticeTimer,renderer,resultShown=false;
try{renderer=new BattlefieldRenderer($('battlefield'),$('battleOverlay'),document.querySelectorAll('[data-lane]'));}catch(error){$('battleState').textContent='3D RENDERING UNAVAILABLE';$('floatingNotice').classList.add('visible');$('floatingNotice').textContent=`${error.message} Try a browser with WebGL enabled.`;$('startBtn').disabled=true;$('startBtn').textContent='WebGL required';}
function notice(message){$('floatingNotice').textContent=message;$('floatingNotice').classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('floatingNotice').classList.remove('visible'),3200);}
function renderLeaders(){
 $('leaderOptions').innerHTML=Object.entries(LEADERS).map(([key,l])=>`<button class="leader-option ${key===chosen?'selected':''}" data-leader="${key}" aria-pressed="${key===chosen}"><img src="assets/${key}.jpg" alt="${l.name}, ${l.title}"><span class="leader-check">✓</span><div class="option-info"><h3>${l.name}</h3><small>${l.title}</small><strong>${l.doctrine}</strong><p>${l.detail}</p></div></button>`).join('');
 $('leaderSelectionText').textContent=LEADERS[chosen].style;
 $('leaderOptions').querySelectorAll('button').forEach(button=>button.onclick=()=>{chosen=button.dataset.leader;renderLeaders();});
}
function updateCommander(){for(let side=0;side<2;side++){const prefix=side?'enemy':'your',key=battle.sides[side].leader,l=LEADERS[key];$(`${prefix}Portrait`).src=`assets/${key}.jpg`;$(`${prefix}Portrait`).alt=`${l.name} character card artwork`;$(`${prefix}Name`).textContent=l.name;$(`${prefix}Title`).textContent=l.title;$(`${prefix}House`).textContent=l.house.toUpperCase();if(side){$('enemyDoctrine').textContent=l.doctrine;$('enemyDoctrineText').textContent=l.detail;}}}
function start(){battle=new Battle(chosen,82);lane=1;running=true;paused=false;resultShown=false;speed=1;handStamp='';accumulator=0;$('leaderDialog').close();if($('resultDialog').open)$('resultDialog').close();$('speedBtn').textContent='1×';$('pauseBtn').textContent='Ⅱ';$('pauseBtn').setAttribute('aria-label','Pause battle');try{localStorage.setItem('oath-live-leader',chosen);}catch{}updateCommander();selectLane(1);updateUI();notice('Tap a Front on the battlefield, then play a card to deploy there.');}
function selectLane(value){lane=value;document.querySelectorAll('[data-lane]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.lane)===lane);b.setAttribute('aria-pressed',String(Number(b.dataset.lane)===lane));});$('frontName').innerHTML=`${['West','Center','East'][lane]} Front <span>→</span>`;updateFrontSummary();}
function updateFrontSummary(){const ours=battle.allies(0,lane).length,theirs=battle.allies(1,lane).length;$('frontSummary').textContent=ours||theirs?`${ours} allied · ${theirs} enemy squads\nCards target this Front.`:'Tap the field, then play a card.';}
function play(index){if(!running){$('leaderDialog').showModal();return;}if(paused){notice('Resume the battle to issue an order.');return;}const card=battle.card(battle.sides[0].hand[index]);const result=battle.play(0,index,lane);if(!result.ok){notice(result.error);return;}if(result.key==='fire')notice('FIRE ARROWS ACTIVE · Every allied archer, on every Front. New squads inherit it.');else notice(`${card.name} · ${['West','Center','East'][lane]} Front`);updateUI();}
function renderHand(){const s=battle.sides[0],stamp=s.leader+':'+s.hand.join(',');if(stamp!==handStamp){handStamp=stamp;$('hand').innerHTML=s.hand.map((key,i)=>{const c=battle.card(key);return `<button class="card ${c.tone}" data-card="${i}" title="${c.name} · ${c.cost} Command. ${c.text}" aria-label="${c.name}, ${c.cost} Command. ${c.text}"><span class="key">${i+1}</span><span class="card-cost">${c.cost}</span><span class="card-symbol" aria-hidden="true">${c.icon}</span><span class="card-type">${c.type}</span><span class="card-name">${c.name}</span></button>`;}).join('');$('hand').querySelectorAll('button').forEach(b=>b.onclick=()=>play(Number(b.dataset.card)));}
 $('hand').querySelectorAll('button').forEach((b,i)=>{const key=s.hand[i];b.classList.toggle('unaffordable',s.command<CARDS[key].cost);b.classList.toggle('activated',key==='fire'&&s.fire);b.setAttribute('aria-disabled',String(!!battle.canPlay(0,i,lane)));});
}
function updateUI(){
 for(let side=0;side<2;side++){const s=battle.sides[side],prefix=side?'enemy':'your';$(`${prefix}Hp`).textContent=Math.max(0,s.integrity).toFixed(s.integrity%1===0?0:1);$(`${prefix}HpBar`).style.width=`${s.integrity/25*100}%`;$(`${prefix}Cmd`).textContent=Math.floor(s.command);$(`${prefix}Soul`).textContent=s.soul;}
 const s=battle.sides[0];$('commandFill').style.width=`${s.command*10}%`;$('clock').textContent=time(battle.time);$('deckCount').textContent=`${s.deck.length} deck · ${s.discard.length} discard`;$('yourDoctrines').innerHTML=`<span>${LEADERS[s.leader].doctrine}</span>${s.fire?'<br><span class="fire-chip">♨ Fire Arrows · all allied archers</span>':''}`;$('enemyDoctrines').innerHTML=battle.sides[1].fire?'<span class="fire-chip">♨ Fire Arrows · all enemy archers</span>':'None yet';
 $('squadCount').textContent=`${battle.units.length} squads in the field`;$('battleState').textContent=!running?'AWAITING YOUR COMMAND':battle.result?'BATTLE CONCLUDED':paused?'BATTLE PAUSED':'BOTH ARMIES IN MOTION';
 $('ledger').innerHTML=battle.log.slice(0,7).map(e=>`<p class="${e.side===0?'mine':e.side===1?'theirs':''}"><time>${time(e.time)}</time>${e.text}</p>`).join('');
 let oathText='';battle.sides.forEach((s,i)=>{s.oaths.forEach(o=>{oathText+=`<div class="oath-item"><b>${i?'Enemy':'Your'} ${['West','Center','East'][o.lane]} Oath</b><br>${Math.ceil(o.remaining)}s remaining · 1 Soul bound</div>`;});if(s.debt)oathText+=`<div>${i?'Enemy':'Your'} Soul Debt: ${s.debt}</div>`;});$('oaths').innerHTML=oathText||'A promise carries weight.';
 renderHand();updateFrontSummary();
 if(battle.result&&!resultShown){resultShown=true;$('resultTitle').textContent=battle.result==='victory'?'The oath holds.':battle.result==='draw'?'Two kingdoms fall.':'The line has broken.';$('resultText').textContent=battle.result==='victory'?`Your ${LEADERS[s.leader].name}-led army has broken the enemy Stronghold.`:battle.result==='draw'?'Both Strongholds fell in the same moment. The ledger records a draw.':'Their army reached your Stronghold. A new commander, a new formation, another chance.';$('resultStats').innerHTML=`<div><b>${time(battle.time)}</b><span>BATTLE TIME</span></div><div><b>${s.played}</b><span>CARDS PLAYED</span></div><div><b>${s.kills}</b><span>SQUADS DEFEATED</span></div>`;$('resultDialog').showModal();}
}
function togglePause(){if(!running||battle.result)return;paused=!paused;$('pauseBtn').textContent=paused?'▶':'Ⅱ';$('pauseBtn').setAttribute('aria-label',paused?'Resume battle':'Pause battle');accumulator=0;updateUI();}
document.querySelectorAll('[data-lane]').forEach(b=>b.onclick=()=>selectLane(Number(b.dataset.lane)));
$('startBtn').onclick=start;$('pauseBtn').onclick=togglePause;
$('speedBtn').onclick=()=>{speed=speed===1?2:1;$('speedBtn').textContent=`${speed}×`;};
$('viewBtn').onclick=()=>{if(!renderer)return;renderer.view=renderer.view==='tactical'?'ground':'tactical';$('viewBtn').textContent=renderer.view==='tactical'?'◇ Tactical view':'◇ Ground view';};
$('leaderBtn').onclick=()=>{renderLeaders();$('leaderDialog').showModal();};
$('closeLeader').onclick=()=>$('leaderDialog').close();
$('restartBtn').onclick=()=>{renderLeaders();$('leaderDialog').showModal();};
$('guideBtn').onclick=()=>$('guideDialog').showModal();$('closeGuide').onclick=()=>$('guideDialog').close();$('resumeGuide').onclick=()=>$('guideDialog').close();
$('playAgain').onclick=()=>{$('resultDialog').close();renderLeaders();$('leaderDialog').showModal();};
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(e.key>='1'&&e.key<='5'){e.preventDefault();play(Number(e.key)-1);}if(e.code==='Space'&&e.target===document.body){e.preventDefault();togglePause();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&running&&!paused&&!battle.result)togglePause();});
let last=performance.now(),accumulator=0;
let lastRender=0;
function frame(now){const dt=Math.min(.15,(now-last)/1000);last=now;const blocked=document.querySelector('dialog[open]');if(running&&!paused&&!blocked&&!battle.result){accumulator+=dt*speed;while(accumulator>=1/30){battle.tick(1/30);accumulator-=1/30;}}else accumulator=0;if(!renderer?.software||now-lastRender>50){renderer?.render(battle,lane,now/1000);lastRender=now;}uiTimer+=dt;if(uiTimer>.15){uiTimer=0;updateUI();}requestAnimationFrame(frame);}
renderLeaders();updateCommander();updateUI();$('leaderDialog').showModal();requestAnimationFrame(frame);
